};

/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(vSelObj),
        CORP_NM: $c.stf.getObjectValue(vSelObj)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    if (vsCoPopGb == "SCH") {
        $c.stf.setObjectValue(txb_COM_NM, scwin.arrPar[0].CORP_NM);
        $c.stf.setObjectValue(txb_ISUR_CD, scwin.arrPar[0].ISUR_CD);
    } else {
        var cbdata = "^ ," + scwin.arrPar[0].ISUR_CD + "^" + scwin.arrPar[0].CORP_NM;
        vSelObj.CBData = cbdata;
        $c.stf.setObjectValue(vSelObj, scwin.arrPar[0].ISUR_CD);
    }
};



/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(selObj) {
    if (vsCoPopGb != "SCH") {
        if (vRowCount == 0) return;
    }
    vSelObj = selObj;
    fn_GetPar = fn_GetParIsurCd;
    fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(selObj);
};


/********************************************** 
 * 함수명   : ins_search
 * 설명       : 일자별  표준코드 조회 
 ***********************************************/
scwin.ins_search = function() {
    $c.cm.setColumnProp(grd_Grid, "CHK", "headcheck", false);
    var STD_CD_APPL_CONTN_TP_CD = "";
    //alert('getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_01)'+getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_01));
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_01) == 'Y') STD_CD_APPL_CONTN_TP_CD += '01,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_02) == 'Y') STD_CD_APPL_CONTN_TP_CD += '02,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_11) == 'Y') STD_CD_APPL_CONTN_TP_CD += '11,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_10) == 'Y') STD_CD_APPL_CONTN_TP_CD += '10,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_12) == 'Y') STD_CD_APPL_CONTN_TP_CD += '12,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_04_05) == 'Y') STD_CD_APPL_CONTN_TP_CD += '04,05,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_06) == 'Y') STD_CD_APPL_CONTN_TP_CD += '06,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_07) == 'Y') STD_CD_APPL_CONTN_TP_CD += '07,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_03) == 'Y') STD_CD_APPL_CONTN_TP_CD += '03,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_09) == 'Y') STD_CD_APPL_CONTN_TP_CD += '09,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_13) == 'Y') STD_CD_APPL_CONTN_TP_CD += '13,';
    if ($c.stf.getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_08) == 'Y') STD_CD_APPL_CONTN_TP_CD += '08,';
    if ($c.stf.getObjectValue(ckb_ALL) == ' Y') STD_CD_APPL_CONTN_TP_CD = '';

    //코드부여일, 입금일 입력안됨
    if (($c.stf.getObjectValue(edt_SSTD_CD_GRNT_DD) == "" || $c.stf.getObjectValue(edt_ESTD_CD_GRNT_DD) == "") &&
        ($c.stf.getObjectValue(edt_SFEE_DEPO_DD) == "" || $c.stf.getObjectValue(edt_EFEE_DEPO_DD) == "")) {
        $c.win.alert(" 코드부여일 또는 입금일을 3년 이내로 입력해야 합니다.");
        edt_SSTD_CD_GRNT_DD.focus();
        return false;
    } else {
        //코드부여일 또는 입금일 입력되었다.
        // 3년 이내 체크.
        if (($c.stf.getObjectValue(edt_SSTD_CD_GRNT_DD) != "" && $c.stf.getObjectValue(edt_ESTD_CD_GRNT_DD) != "") &&
            eval($c.ut.cGetPlusYear(edt_SSTD_CD_GRNT_DD.getValue(), 3)) < eval(edt_ESTD_CD_GRNT_DD.getValue())) {
            $c.win.alert("코드부여일의 검색 기간은 3년 이내로만 가능합니다.");
            edt_SSTD_CD_GRNT_DD.focus();
            return false;
        }
        if (($c.stf.getObjectValue(edt_SFEE_DEPO_DD) != "" && $c.stf.getObjectValue(edt_EFEE_DEPO_DD) != "") &&
            eval($c.ut.cGetPlusYear(edt_SFEE_DEPO_DD.getValue(), 3)) < eval(edt_EFEE_DEPO_DD.getValue())) {
            $c.win.alert("입금일의 검색 기간은 3년 이내로만 가능합니다.");
            edt_SFEE_DEPO_DD.focus();
            return false;
        }
    }

    // 코드부여일 순서 체크
    if ($c.stf.compareFromToDate2(edt_SSTD_CD_GRNT_DD, edt_ESTD_CD_GRNT_DD) == false) {
        return false;
    }
    // 입금일 순서 체크
    if ($c.stf.compareFromToDate2(edt_SFEE_DEPO_DD, edt_EFEE_DEPO_DD) == false) {
        return false;
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS21310_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listdayGrntFeeListInquiry" + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}STD_CD_APPL_CONTN_TP_CD=" + STD_CD_APPL_CONTN_TP_CD + "&{P}STD_CD=" + txb_pSTD_CD.getValue() + "&{P}STD_CD_GRNT_FEE_PROCS_STAT_CD=" + $c.stf.getObjectValue(cmb_GRNT_FEE_PROCS_STAT_CD) + "&{P}SSTD_CD_GRNT_DD=" + edt_SSTD_CD_GRNT_DD.getValue() + "&{P}ESTD_CD_GRNT_DD=" + edt_ESTD_CD_GRNT_DD.getValue() + "&{P}SFEE_DEPO_DD=" + edt_SFEE_DEPO_DD.getValue() + "&{P}EFEE_DEPO_DD=" + edt_EFEE_DEPO_DD.getValue();
    //alert(url); 
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};
scwin.ins_fee_return = function() {
    //alert('수수료환급처리');
    var msg = $c.stf.getMessageParam("MSG-A006", "수수료환급");
    var res = window.confirm(msg);
    if (res) {
        // 선택된 Row만 서버로 전송..
        scwin.fn_SetTransData();
        trs_Return.Action = "/PrepayInfoAction.do?method=registerFeeReturn" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Return.KeyName = "toinb_dataid4";
        trs_Return.KeyValue = "JSP(I:pInput=dts_List)";
        trs_Return.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
        trs_Return.Post();
    }
};



/**
 * 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 */
scwin.fn_SetTransData = function() {
    var nRow = dts_List.getRowPosition();
    dts_List.setCellData(nRow, "CHK", "T");
};
scwin.fn_allCheck = function() {
    var checkArray = [ckb_STD_CD_APPL_CONTN_TP_CD_01, ckb_STD_CD_APPL_CONTN_TP_CD_02, ckb_STD_CD_APPL_CONTN_TP_CD_11, ckb_STD_CD_APPL_CONTN_TP_CD_10, ckb_STD_CD_APPL_CONTN_TP_CD_12, ckb_STD_CD_APPL_CONTN_TP_CD_04_05, ckb_STD_CD_APPL_CONTN_TP_CD_06, ckb_STD_CD_APPL_CONTN_TP_CD_08, ckb_STD_CD_APPL_CONTN_TP_CD_07, ckb_STD_CD_APPL_CONTN_TP_CD_03, ckb_STD_CD_APPL_CONTN_TP_CD_09, ckb_STD_CD_APPL_CONTN_TP_CD_13];
    if (ckb_ALL.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // ISUR_APPL_ID  
    scwin.arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_chkValid
 * 설명       : 일괄발급 영수증 체크대상을 알아낸다.
 ***********************************************/
scwin.fn_chkClickValid = function(col, colid, bCheck) {
    //alert("col : " + col);
    //alert(" colid: " + colid);
    //alert(" bCheck: " + bCheck);

    if (bCheck == '1') {
        //체크선택
        if ("미납" == (dts_List.getCellData(col, "STD_CD_GRNT_FEE_PROCS_STAT_NM")) ||
            "면제" == (dts_List.getCellData(col, "STD_CD_GRNT_FEE_PROCS_STAT_NM"))) {
            $c.win.alert("미납 이나 면제건은 영수증을 발급할 수 없습니다.");
            dts_List.setCellData(col, "CHK", "0");
            return false;
        }
    }
};



/********************************************** 
 * 함수명   : fn_chkValid
 * 설명       : 일괄발급 영수증 체크대상을 알아낸다.
 ***********************************************/
scwin.fn_chkValid = function() {
    var cnt = 0;
    var cnt2 = 0;
    var cnt3 = 0;
    var visurCd = "";
    var vDepDd = "";
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") == "T") {
            cnt++;
            if (cnt == 1) {
                visurCd = dts_List.getCellData(nRow, "ISUR_CD");
                vDepDd = dts_List.getCellData(nRow, "FEE_DEPO_DD");
            } else if (cnt > 1) {
                if (visurCd != dts_List.getCellData(nRow, "ISUR_CD")) {
                    cnt2++;
                }
            }
            if ("미납" == (dts_List.getCellData(nRow, "STD_CD_GRNT_FEE_PROCS_STAT_NM")) ||
                "면제" == (dts_List.getCellData(nRow, "STD_CD_GRNT_FEE_PROCS_STAT_NM"))) {
                cnt3++;
            }
        }
    }
    //alert("cnt: " +cnt);
    if (eval(cnt) == 0) {
        $c.win.alert("영수증 일괄발급 대상을 체크하세요.");
        return false;
    }
    if (eval(cnt2) > 0) {
        $c.win.alert("영수증 일괄발급은 동일한 발행기관에 대해서만 가능합니다.");
        return false;
    }
    if (eval(cnt3) > 0) {
        $c.win.alert("미납 이나 면제건은 영수증을 발급할 수 없습니다.");
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_setCheckBox
 * 설명       : 그리드 체크박스 전체선택 또는 전체선택 해제
 ***********************************************/
scwin.fn_setCheckBox = function(grdObj, dtsObj, bCheck) {
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "STD_CD_GRNT_FEE_PROCS_STAT_CD") == '5' || dtsObj.getCellData(i, "STD_CD_GRNT_FEE_PROCS_STAT_CD") == '9') {
            //5:미납, 9 :면제
            dtsObj.setCellData(i, "CHK", "F");
        } else {
            dtsObj.setCellData(i, "CHK", vcd);
        }
    }
    grdObj.setBroadcast(true);
};


/********************************************** 
 * 함수명   : fn_print
 * 설명       : 보고서 출력
 ***********************************************/
scwin.fn_print = function() {
    // 출력 대상 데이타체크
    if (scwin.fn_chkValid() == false) return;
    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    //dts_Report.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 


    //데이타셋 
    //var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    var i = 0;
    var iTotFeeAmt = 0; //총 수수료액
    var vIsuNm = ""; //종목명 ~외 X건
    var vStdCd = ""; //종목코드 ~외 X건
    var vComNm = "";
    var vDepoDd = "";
    for (var cnt = 1; cnt <= dts_List.getTotalRow(); cnt++) {
        if (dts_List.getCellData(cnt, "CHK") == "T") {
            i++;
            dts_Report.insertRow();
            dts_Report.setCellData(i, "NO", i);
            dts_Report.setCellData(i, "STD_CD_GRNT_DD", dts_List.getCellData(cnt, "STD_CD_GRNT_DD"));
            dts_Report.setCellData(i, "STD_CD", dts_List.getCellData(cnt, "STD_CD"));
            dts_Report.setCellData(i, "ISU_NM", dts_List.getCellData(cnt, "MASTER_ISU_NM")); //종목명 조회는 신청T 에서 가져오고 일괄영수증은 마스터T에서 가져온다.
            //dts_Report.NameString(i, "ISU_NM") = dts_List.NameString(cnt, "ISU_NM"); //종목명+고유명으로 변경
            dts_Report.setCellData(i, "STD_CD_GRNT_FEE", fn_SetComma(dts_List.getCellData(cnt, "STD_CD_GRNT_FEE")));
            dts_Report.setCellData(i, "FEE_DEPO_DD", dts_List.getCellData(cnt, "FEE_DEPO_DD"));
            if (i == 1) {
                vIsuNm = dts_List.getCellData(cnt, "MASTER_ISU_NM"); //종목명+고유명으로 변경
                vStdCd = dts_List.getCellData(cnt, "STD_CD");
                vComNm = dts_List.getCellData(cnt, "COM_NM");
            }
            iTotFeeAmt = iTotFeeAmt + eval(dts_List.getCellData(cnt, "STD_CD_GRNT_FEE"));
        }
    }
    if (i > 1) {
        vIsuNm = vIsuNm + " 외 " + (i - 1) + "건";
        vStdCd = vStdCd + " 외 " + (i - 1) + "건";
    }
    var sTotFeeAmt = iTotFeeAmt + "";
    var num1 = "";
    var num2 = "";
    var num3 = "";
    var num4 = "";
    var num5 = "";
    var num6 = "";
    var num7 = "";
    var num8 = "";
    var num9 = "";
    if (sTotFeeAmt.length >= 1) {
        num1 = sTotFeeAmt.substring(sTotFeeAmt.length - 1, sTotFeeAmt.length);
    } //1의자리(일)
    if (sTotFeeAmt.length >= 2) {
        num2 = sTotFeeAmt.substring(sTotFeeAmt.length - 2, sTotFeeAmt.length - 1);
    } //2의자리(십)
    if (sTotFeeAmt.length >= 3) {
        num3 = sTotFeeAmt.substring(sTotFeeAmt.length - 3, sTotFeeAmt.length - 2);
    } //3의자리(백)
    if (sTotFeeAmt.length >= 4) {
        num4 = sTotFeeAmt.substring(sTotFeeAmt.length - 4, sTotFeeAmt.length - 3);
    } //4의자리(천)
    if (sTotFeeAmt.length >= 5) {
        num5 = sTotFeeAmt.substring(sTotFeeAmt.length - 5, sTotFeeAmt.length - 4);
    } //5의자리(만)
    if (sTotFeeAmt.length >= 6) {
        num6 = sTotFeeAmt.substring(sTotFeeAmt.length - 6, sTotFeeAmt.length - 5);
    } //6의자리(십)
    if (sTotFeeAmt.length >= 7) {
        num7 = sTotFeeAmt.substring(sTotFeeAmt.length - 7, sTotFeeAmt.length - 6);
    } //7의자리(백)
    if (sTotFeeAmt.length >= 8) {
        num8 = sTotFeeAmt.substring(sTotFeeAmt.length - 8, sTotFeeAmt.length - 7);
    } //8의자리(천)
    if (sTotFeeAmt.length >= 9) {
        num9 = sTotFeeAmt.substring(sTotFeeAmt.length - 9, sTotFeeAmt.length - 8);
    } //9의자리(억)

    //alert('[num1]'+num1+'[num2]'+num2+'[num3]'+num3+'[num4]'+num4+'[num5]'+num5+'[num6]'+num6+'[num7]'+num7+'[num8]'+num8+'[num9]'+num9);
    if (sTotFeeAmt.length == 4) {
        num5 = '￦';
    } //5의자리(만)
    else if (sTotFeeAmt.length == 5) {
        num6 = '￦';
    } //6의자리(십)
    else if (sTotFeeAmt.length == 6) {
        num7 = '￦';
    } //7의자리(백)
    else if (sTotFeeAmt.length == 7) {
        num8 = '￦';
    } //8의자리(천)
    else if (sTotFeeAmt.length == 8) {
        num9 = '￦';
    } //9의자리(억)

    var keys = ['noArr', 'stdCdGrntDdArr', 'stdCdArr', 'isuNmArr', 'stdCdGrntFeeArr', 'feeDepoDdArr'];

    //alert('[sTotFeeAmt]'+sTotFeeAmt);
    //var testDateSet = rex_gfGetGauceCsvStr(dts_Print, dts_Report);
    var testDateSet = getNewReportArrayValue(keys, dts_Report);
    //alert('[testDateSet]'+testDateSet);

    //Rexpert리포트 파일명 
    //var rex_rptname = "test/sample4";
    var rex_rptname = "RLDINS00002";
    scwin.userParam = [{
        uid: "comNm",
        unm: vComNm
    }, {
        uid: "stdCd",
        unm: vStdCd
    }, {
