        num6 = '\'} //6의자리(십);if(sTotFeeAmt.length==6 ) {  	
        num7 = '\'} //7의자리(백);if(sTotFeeAmt.length==7 ) {  	
        num8 = '\'} //8의자리(천);if(sTotFeeAmt.length==8 ) {  	
        num9 = '\'} //9의자리(억);

        //alert('[sTotFeeAmt]'+sTotFeeAmt);
        var testDateSet = rex_gfGetGauceCsvStr(dts_Print, dts_Report);
        //alert('[testDateSet]'+testDateSet);

        //Rexpert리포트 파일명 
        //var rex_rptname = "test/sample4";
        var rex_rptname = "RLDINS00002";
        scwin.userParam = [{
            uid: "COM_NM",
            unm: vComNm
        }, {
            uid: "STD_CD",
            unm: vStdCd
        }, {
            uid: "ISU_NM",
            unm: vIsuNm
        }, {
            uid: "NUM1",
            unm: num1
        }, {
            uid: "NUM2",
            unm: num2
        }, {
