    function dts_List_OnLoadCompleted(rowcount) {
        if (dts_List.errorMsg) {
            $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
        $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

        if (dts_List.getTotalRow() > 0) {
            //grd_Grid.ColumnProp("GUBUN","SumText") = "합계";

            var sum1 = 0;
            for (i = 1; i <= dts_List.getTotalRow(); i++) {
                sum1 = sum1 + eval(dts_List.getCellData(i, "STD_CD_GRNT_FEE"));
            }
            //수수료 합계 
            $c.cm.setColumnProp(grd_Grid, "STD_CD_GRNT_FEE", "SumText", $c.stf.FormatNumberEx(sum1, 3));
        } else {
            $c.cm.setColumnProp(grd_Grid, "STD_CD_GRNT_FEE", "SumText", "");
        }
    };

