    function grd_Grid_OnDblClick(row, colid) {
        //	alert("X");
        if (row == 0) return;
        if (colid == "STD_CD_APPL_ID") {
            var sStdCd = dts_List.getCellData(row, "STD_CD_APPL_ID"); // STD_CD_APPL_ID 

            if (sStdCd != "") {
                var CONTN_TP_CD = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_CD");
                var STD_CD = dts_List.getCellData(row, "STD_CD");
                var sKnd = "";
                //alert("CONTN_TP_CD ::" +CONTN_TP_CD);
                //if (KND == "지표" || KND == "선물옵션" || KND == "스트립"){
                //	txb_param1.value = dts_List.NameValue(row,"STD_CD");
                //}else{
                //	txb_param1.value = dts_List.NameValue(row,"STD_CD_APPL_ID");
                //}

                if (CONTN_TP_CD == "02") {
                    sKnd = "주권";
                } else if (CONTN_TP_CD == "10") {
                    sKnd = "주식워런트";
                } else if (CONTN_TP_CD == "11") {
                    sKnd = "ELS_DLS";
                } else if (CONTN_TP_CD == "12") {
                    sKnd = "ETN";
                } else if (CONTN_TP_CD == "77") {
                    sKnd = "전자단기사채";
                }
                txb_param1.setValue(STD_CD);
                //txb_param2.value = "R";
                fn_GetPar = fn_GetParam;
                ins_ViewIsuMaster(sKnd, STD_CD);
            }
        } else if (colid == "MASTER_ISU_NM") {
            var vSEC_KND_CD = row; //ROW 임의지정
            var vSEC_KND_NM = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_NM"); //상품구분

            await $c.frame.CreateDialogFrame("READ|SEC_KND_CD=" + vSEC_KND_CD + "&SEC_KND_NM=" + vSEC_KND_NM, "/common/ULDINS94330.gfm", "개별코드부여수수료조회", 10, 10, 640, 400, "window");
        }
    };

